# FUNCIÓN GENERADORA
def obtener_prompt(nombre_modelo):
    regla_especifica = REGLAS_ESPECIFICAS.get(nombre_modelo, "")
    
    # Ensamblamos las 3 partes
    prompt_completo = f"{INTRO_GENERAL}\n{regla_especifica}\n{FORMATO_FINAL}"
    return prompt_completo